"""Low level user interaction functions for the VolumeView Reference window. Used by the VolumeViewReferenceObjects page object class"""

from .objects.xvi_volume_view_reference_objects import VolumeViewReferenceObjects
from interops.libraries.squish_actions import CommonActions
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import XVI_REGISTRATION_APP_NAME # Note: VolumeView Reference window uses the same AUT name as Registration window

def __find_main_volume_view_reference_window(timeout: int=3000):
    """Searches for the main VolumeView Reference window. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the volume_view_reference_functions.py file

    :param int timeout: Time to wait for the main reference window object to be found
    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(VolumeViewReferenceObjects.main_Volume_View_Reference_Window, timeout) is not None else False

def __find_volume_view_reference_approval_dialog():
    """Searches for the Reference Approval Dialog. Returns True if successfully located.

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(VolumeViewReferenceObjects.volume_View_Reference_Approval_Window) is not None else False

def __find_volume_view_reference_margin_for_mask_dialog():
    """Searches for the Margin for mask (0-2 cm) Dialog. Returns True if successfully located.

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(VolumeViewReferenceObjects.volume_View_Reference_Margin_For_Mask_Window) is not None else False

def __locate_reference_checkbox_by_child_object_index(childObjIndex: int) -> object:
    """Searches Reference pane child objects based on the positional index and finds the checkbox within
    the list of child objects. Returns object if successfully located. Assumes that the ordering of the
    child objects remains constant.

    Used for checkboxes that don't have a unique object property, but can be identified by drilling down
    the object tree and narrowing the search within a specific pane.

    :param int childObjIndex: Index of the child object in the pane object to be searched
    :return: found object
    :rtype: object
    """
    if __find_main_volume_view_reference_window():
        reference_pane_obj_list = CommonActions.get_child_objects(VolumeViewReferenceObjects.volume_View_Reference_Pane)

        if len(reference_pane_obj_list) > 0:
            checkbox_object = reference_pane_obj_list[childObjIndex]
            return checkbox_object

def __locate_protocol_combobox_by_child_object_index(childObjIndex: int) -> object:
    """Searches Protocol pane child objects based on the positional index and finds the combobox within
    the list of child objects. Returns object if successfully located. Assumes that the ordering of the
    child objects remains constant.

    Used for comboboxes that don't have a unique object property, but can be identified by drilling down
    the object tree and narrowing the search within a specific pane.

    :param int childObjIndex: Index of the child object in the pane object to be searched
    :return: found object
    :rtype: object
    """
    if __find_main_volume_view_reference_window():
        protocol_pane_obj_list = CommonActions.get_child_objects(VolumeViewReferenceObjects.volume_View_Protocal_Pane)

        if len(protocol_pane_obj_list) > 0:
            combobox_object = protocol_pane_obj_list[childObjIndex]
            return combobox_object

@deco.set_separate_app_context(application_name=XVI_REGISTRATION_APP_NAME)
def wait_for_volume_view_reconstruction_pane(wait_timeout: int) -> bool:
    """Waits for the main VolumeView Reference Reconstruction pane to exist. Returns True if successfully located.
    """
    return True if CommonActions.wait_for_object_exists(VolumeViewReferenceObjects.volume_View_Reconstruction_Pane, wait_timeout) is not None else False

# --------------------------------------- Reference pane interactions ---------------------------------------

@deco.set_separate_app_context(application_name=XVI_REGISTRATION_APP_NAME)
def check_volume_view_reference_clipbox_locked_context_menu_item() -> None:
    """Locates the main VolumeView Reference window > then left mouse click on the Clipbox button in the
    Reference pane, followed by the Locked context menu item only if its unchecked and enabled
    """
    if __find_main_volume_view_reference_window():
        CommonActions.left_click_object_no_move(VolumeViewReferenceObjects.volume_View_Reference_Clipbox_Button)

        locked_context_menu_state = CommonActions.get_checkbox_state(VolumeViewReferenceObjects.volume_View_Reference_Clipbox_Context_Menu)
        if not locked_context_menu_state:
            CommonActions.left_click_object_no_move(VolumeViewReferenceObjects.volume_View_Reference_Clipbox_Context_Menu)
        else:
            # Click away from context menu if locked context menu item already checked
            clipboard_button = CommonActions.find_object(VolumeViewReferenceObjects.volume_View_Reference_Clipbox_Button)
            CommonActions.mouse_press_hold_and_release_with_negative_y_offset(clipboard_button, yOffsetValue=20, mousePressDuration=0.5)

@deco.set_separate_app_context(application_name=XVI_REGISTRATION_APP_NAME)
def uncheck_volume_view_reference_clipbox_locked_context_menu_item() -> None:
    """Locates the main VolumeView Reference window > then left mouse click on the Clipbox button in the
    Reference pane, followed by the Locked context menu item only if its checked and enabled
    """
    if __find_main_volume_view_reference_window():
        CommonActions.left_click_object_no_move(VolumeViewReferenceObjects.volume_View_Reference_Clipbox_Button)

        locked_context_menu_state = CommonActions.get_checkbox_state(VolumeViewReferenceObjects.volume_View_Reference_Clipbox_Context_Menu)
        if locked_context_menu_state:
            CommonActions.left_click_object_no_move(VolumeViewReferenceObjects.volume_View_Reference_Clipbox_Context_Menu)
        else:
            # Click away from context menu if locked context menu item already unchecked
            clipboard_button = CommonActions.find_object(VolumeViewReferenceObjects.volume_View_Reference_Clipbox_Button)
            CommonActions.mouse_press_hold_and_release_with_negative_y_offset(clipboard_button, yOffsetValue=20, mousePressDuration=0.5)

@deco.set_separate_app_context(application_name=XVI_REGISTRATION_APP_NAME)
def check_volume_view_reference_clipbox_checkbox() -> None:
    """Locates the main VolumeView Reference window > then left mouse click on the Reference Clipbox checkbox only if its enabled and unchecked
    """
    CLIPBOX_OBJ_IDX = 9 # Clipbox object is index no. 9 in the list of Reference pane child objects
    volume_view_reference_clipbox_checkbox = __locate_reference_checkbox_by_child_object_index(childObjIndex=CLIPBOX_OBJ_IDX)

    if not CommonActions.get_checkbox_state(volume_view_reference_clipbox_checkbox):
        CommonActions.left_click_object_no_move(volume_view_reference_clipbox_checkbox)

