@deco.set_separate_app_context(application_name=XVI_REGISTRATION_APP_NAME)
def edit_margin_for_mask_field(valueToSet: float) -> None:
    """Locates the Margin for mask (0-2 cm) window > then enters the specified text

    :param float valueToSet: Value to be entered in the Margin for mask 'Value (cm)' field
    """
