@deco.set_separate_app_context(application_name=XVI_REGISTRATION_APP_NAME)
def get_current_volume_view_registration_method_from_combobox() -> str:
    """Locates the main VolumeView Preset Selection window > then retrieves the current text from the Main ComboxBox
    """
    if __find_main_volume_view_reference_window():
        text_value = CommonActions.get_uneditable_field_objects_text_value(VolumeViewReferenceObjects.volume_View_Reference_Method_ComboBox)
        if text_value is not None:
            return text_value.strip()
    return ""

